t.script:
                (function(){
                    function fetchVouchers(){
                        var grid = document.getElementById('voucher_grid');
                        odoo.jsonRpc('/wuchang/tickets/list', 'call', {}).then(function(res){
                            grid.innerHTML = '';
                            if (!res.items || res.items.length === 0) {
                                grid.innerHTML = '
暫無可購買的票券';
                                return;
                            }

                            (res.items||[]).forEach(function(v){
                                var card = document.createElement('div');
                                card.className = 'bg-white rounded-xl border border-gray-100 shadow-sm overflow-hidden flex';

                                var leftSide = '
';
                                leftSide += '
'; // Sawtooth effect
                                leftSide += '價值';
                                leftSide += '$' + v.price + '';
                                leftSide += '';

                                var rightSide = '
';
                                rightSide += '
';
                                rightSide += '
';
                                rightSide += '
' + v.name + '';
                                rightSide += '';
                                rightSide += '
' + v.merchant + '';
                                rightSide += '';

                                rightSide += '
';
                                rightSide += '剩餘 ' + v.stock + ' 張';
                                rightSide += '立即兌換';
                                rightSide += '';
                                rightSide += '';

                                card.innerHTML = leftSide + rightSide;
                                grid.appendChild(card);
                            });

                            // Update balance (simulated)
                            document.getElementById('user_coin_balance').innerText = '888';
                        });
                    }

                    window.buyTicket = function(id) {
                        if(confirm('確定要使用幸福幣兌換此票券嗎？')) {
                            odoo.jsonRpc('/wuchang/tickets/buy', 'call', {voucher_id: id}).then(function(res){
                                if(res.success) {
                                    alert(res.message);
                                    // Refresh logic here if needed
                                }
                            });
                        }
                    };

                    document.addEventListener('DOMContentLoaded', fetchVouchers);
                })();
